<script>
import TitleLine from '../portal/modules/TitleLine'
import { getTaskList, kaiAct, lingAct, getActchouhljOpennums } from '@/api/user'
// import nodata from '@/assets/portal/nodata.png'
export default {
  components: {
    TitleLine
  },
  props: {
  },
  data() {
    return {
      showPrize:false,
      showConfirm: false,
      showDialog: false,
      tkcontent: '',
      imgUrl: '',
      currentPage: 1,
      time: '',
      //   nodata: nodata,
      title: this.$t('rwzx.rwzx01'),
      recordList: [
      ],
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10,
      currentItem: null,
      currentActcode: '',
      status: '',
      opennumlist:[]
    }
  },
  mounted() {

  },
  methods: {
    changeSelectItem(i, type) {
      for (let index = 0; index < this.recordList[i].showlist.length; index++) {
        const ele = this.recordList[i].showlist[index]
        if (ele.ischeckshow === '1') {
          if (type === 'add' && index < this.recordList[i].showlist.length - 1) {
            ele.ischeckshow = '0'
            this.recordList[i].showlist[index + 1].ischeckshow = '1'
          } else if (type === 'deduct' && index > 0) {
            ele.ischeckshow = '0'
            this.recordList[i].showlist[index - 1].ischeckshow = '1'
          } else {
            break
          }
          const navList = document.getElementsByClassName('process_list')
          const navWidth = document.getElementsByClassName('process_item')[0].clientWidth
          navList[i].scroll({
            top: 0,
            left: type === 'deduct' ? (index - 1) * navWidth : (index) * navWidth,
            behavior: 'smooth' // 指定滚动行为，支持参数 smooth(平滑滚动),默认值auto(瞬间滚动)
          })
          break
        }
      }
      // this.recordList[i].showlist.forEach((ele, index) => {
      //   if (ele.ischeckshow === '1') {
      //     ele.ischeckshow = '0'
      //     if (type === 'add') {
      //       this.recordList[i].showlist[index + 1].ischeckshow = '1'
      //     } else if (type === 'deduct') {
      //       this.recordList[i].showlist[index - 1].ischeckshow = '1'
      //     }
      //     const navList = document.getElementsByClassName('process_list')
      //     const navWidth = document.getElementsByClassName('process_item')[0].clientWidth
      //     navList[i].scroll({
      //       top: 0,
      //       left: (index - 2) * navWidth,
      //       behavior: 'smooth' // 指定滚动行为，支持参数 smooth(平滑滚动),默认值auto(瞬间滚动)
      //     })
      //     return
      //   }
      // })
    },
    lingMons(actcode, isneedtk, tkcontent, item) {
      this.status = 'ling'
      // if(actcode==='actchouhlj'){
      //   getActchouhljOpennums().then(res => {
      //     // res.opennumlist=[
      //     //   {opennum:'9999',ctime:'2021-12-31 23:59:59'},
      //     //   {opennum:'2999',ctime:'2021-12-31 23:59:59'},
      //     //   {opennum:'4999',ctime:'2021-12-31 23:59:59'}
      //     // ]
      //     if(res.opennumlist.length>0){
      //       this.opennumlist=res.opennumlist
      //       this.showPrize=true
      //     }else{
      //     }
      //   })
      // }
      if (item.lingstatus === '0') {
        if (isneedtk === '1') {
          this.tkcontent = tkcontent
          this.showConfirm = true
          this.currentItem = item
          this.currentActcode = actcode
        } else {
          this.lingAct(actcode, item)
        }
      }
    },
    lingAct(actcode, item) {
      if (item) {
        lingAct({ actcode, levelcount: item.levelcount }).then(res => {
          if(actcode==='actchouhlj') {
            this.opennumlist=res.opennumstr.split(',').map(item=>({opennum:item,ctime:''}))
            this.showPrize=true
          }else{
            this.$toast.success('您已成功领取')
            this.onRefresh()
          }
        })
      } else {
        lingAct({ actcode: this.currentActcode, levelcount: this.currentItem.levelcount }).then(res => {
          this.$toast.success('您已成功领取')
          this.onRefresh()
        })
      }
      this.currentItem = null
      this.currentActcode = ''
    },
    kaiAct(actcode, item) {
      this.currentActcode = actcode
      this.status = 'kai'
      if (item.isneedtk === '1') {
        this.tkcontent = item.tkcontent
        this.showConfirm = true
      } else {
        kaiAct({ actcode }).then(res => {
          this.$toast.success('报名成功')
          this.onRefresh()
        })
      }
    },
    kaiActApi() {
      kaiAct({ actcode: this.currentActcode }).then(res => {
        this.$toast.success('报名成功')
        this.onRefresh()
      })
    },
    circleClick(index, i) {
      this.recordList[index].showlist.forEach(element => {
        element.ischeckshow = '0'
      })
      this.recordList[index].showlist[i].ischeckshow = '1'
    },
    showRule(url) {
      this.imgUrl = url
      this.showDialog = true
    },
    async onLoad() { //, ucode: this.$store.getters.userInfo.ucode
      const res = await getTaskList({ pages: this.pageNum })
      // for (let index = 0; index < res.actlist.length; index++) {
      //   if(res.actlist[index].actcode==='actchouhlj'){
      //     res.actlist[index].showlist[0].lingstatus='0'
      //   }
      // }
      if (this.refreshing) {
        this.recordList = []
        this.refreshing = false
      }
      this.recordList = this.recordList.concat(res.actlist)
      this.loading = false
      this.pageNum++
      if (!res.totalrow) {
        this.finished = true
      }
      if (this.recordList.length >= Number(res.totalrow)) {
        this.finished = true
      }
      await this.$nextTick()
      if (this.$route.query.actcode) {
        const i = this.recordList.findIndex(item => item.actcode === this.$route.query.actcode)
        // const navList = document.getElementsByClassName('process_list')
        const navWidth = document.getElementsByClassName('list_box1')[0].clientHeight
        window.scroll({
          top: i * navWidth,
          left: 0,
          behavior: 'smooth' // 指定滚动行为，支持参数 smooth(平滑滚动),默认值auto(瞬间滚动)
        })
      }
      for (let index = 0; index < this.recordList.length; index++) {
        if (this.recordList[index].showlist && this.recordList[index].showlist.length > 0) {
          const j = this.recordList[index].showlist.findIndex(obj => obj.ischeckshow === '1')
          const navList = document.getElementsByClassName('process_list')
          const navWidth = document.getElementsByClassName('process_item')[0].clientWidth
          navList[index].scroll({
            top: 0,
            left: j * navWidth,
            behavior: 'smooth' // 指定滚动行为，支持参数 smooth(平滑滚动),默认值auto(瞬间滚动)
          })
        }
      }
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    }
  }
}
</script>
